package com.networknt.schema;

import java.lang.reflect.Field;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;

import com.fasterxml.jackson.databind.JsonNode;
import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;

/**
 * Unit tests for {@link JsonSchema#initializeValidators()}.
 *
 * The tests use reflection to create a {@link JsonSchema} instance (its
 * constructor is private) and to manipulate the internal {@code validators}
 * and {@code validatorsLoaded} fields.  This avoids the need for external
 * mocking frameworks.
 */
class JsonSchema_initializeValidators_Test {

    /**
     * Minimal {@link JsonValidator} implementation that records how many times
     * {@code preloadJsonSchema()} is invoked and can be configured to throw an
     * exception.
     */
    private static class StubValidator implements JsonValidator {

        private final AtomicInteger preloadCalls = new AtomicInteger(0);
        private RuntimeException toThrow;

        void setException(RuntimeException ex) {
            this.toThrow = ex;
        }

        int getPreloadCalls() {
            return preloadCalls.get();
        }

        @Override
        public void preloadJsonSchema() {
            if (toThrow != null) {
                throw toThrow;
            }
            preloadCalls.incrementAndGet();
        }

        /* The remaining methods of the JsonValidator interface are not needed for
         * these tests, so they are implemented as no‑ops. */
        @Override
        public Set<ValidationMessage> validate(ExecutionContext executionContext, JsonNode node,
                                                JsonNode rootNode, JsonNodePath instanceLocation) {
            return Collections.emptySet();
        }

        @Override
        public Set<ValidationMessage> validate(ExecutionContext executionContext, JsonNode node,
                                                JsonNode rootNode, JsonNodePath instanceLocation,
                                                boolean failFast) {
            return Collections.emptySet();
        }

        @Override
        public void setSchema(JsonSchema schema) {
            // no‑op
        }

        @Override
        public JsonSchema getSchema() {
            return null;
        }

        @Override
        public String getErrorMessageKey() {
            return null;
        }

        @Override
        public String getErrorMessage() {
            return null;
        }

        @Override
        public Keyword getKeyword() {
            return null;
        }
    }

    /**
     * Creates a {@link JsonSchema} instance using its private constructor and
     * injects the supplied validator list and the {@code validatorsLoaded}
     * flag.
     */
    private static JsonSchema createSchema(List<JsonValidator> validators,
                                            boolean validatorsLoaded) throws Exception {
        // The private constructor signature:
        // JsonSchema(ValidationContext, SchemaLocation, JsonNodePath,
        //            JsonNode, JsonSchema, boolean)
        java.lang.reflect.Constructor<JsonSchema> ctor =
                JsonSchema.class.getDeclaredConstructor(
                        ValidationContext.class,
                        SchemaLocation.class,
                        JsonNodePath.class,
                        JsonNode.class,
                        JsonSchema.class,
                        boolean.class);
        ctor.setAccessible(true);
        JsonSchema schema = ctor.newInstance(
                null, null, null, null, null, false);

        // inject validators list
        Field validatorsField = JsonSchema.class.getDeclaredField("validators");
        validatorsField.setAccessible(true);
        validatorsField.set(schema, validators);

        // inject validatorsLoaded flag
        Field loadedField = JsonSchema.class.getDeclaredField("validatorsLoaded");
        loadedField.setAccessible(true);
        loadedField.setBoolean(schema, validatorsLoaded);

        return schema;
    }

    /**
     * Helper to read the private {@code validatorsLoaded} flag via reflection.
     */
    private static boolean isValidatorsLoaded(JsonSchema schema) throws Exception {
        Field f = JsonSchema.class.getDeclaredField("validatorsLoaded");
        f.setAccessible(true);
        return (boolean) f.get(schema);
    }

    /**
     * Helper to replace the validator list of an existing schema.
     */
    private static void setValidators(JsonSchema schema, List<JsonValidator> validators) throws Exception {
        Field validatorsField = JsonSchema.class.getDeclaredField("validators");
        validatorsField.setAccessible(true);
        validatorsField.set(schema, validators);
    }

    @Test
    void initializeValidators_callsPreloadWhenNotYetLoaded() throws Exception {
        // GIVEN a JsonSchema whose validators have not been loaded yet
        StubValidator validator1 = new StubValidator();
        StubValidator validator2 = new StubValidator();
        List<JsonValidator> validators = Arrays.asList(validator1, validator2);
        JsonSchema schema = createSchema(validators, false);

        // WHEN initializeValidators() is invoked
        schema.initializeValidators();

        // THEN each validator's preloadJsonSchema() should be called exactly once
        Assertions.assertEquals(1, validator1.getPreloadCalls(),
                "validator1 should be preloaded once");
        Assertions.assertEquals(1, validator2.getPreloadCalls(),
                "validator2 should be preloaded once");
    }

    @Test
    void initializeValidators_doesNotCallPreloadWhenAlreadyLoaded() throws Exception {
        // GIVEN a JsonSchema whose validators are already marked as loaded
        StubValidator validator = new StubValidator();
        List<JsonValidator> validators = Collections.singletonList(validator);
        JsonSchema schema = createSchema(validators, true);

        // WHEN initializeValidators() is invoked
        schema.initializeValidators();

        // THEN no preloadJsonSchema() call should occur
        Assertions.assertEquals(0, validator.getPreloadCalls(),
                "validator should not be preloaded when flag is already true");
    }

    @Test
    void initializeValidators_preloadThrowsException_stopsIteration() throws Exception {
        // badValidator will throw when preloadJsonSchema() is called
        StubValidator badValidator = new StubValidator();
        badValidator.setException(new RuntimeException("preload failure"));
        StubValidator goodValidator = new StubValidator();
        List<JsonValidator> validators = Arrays.asList(badValidator, goodValidator);
        JsonSchema schema = createSchema(validators, false);

        RuntimeException ex = Assertions.assertThrows(RuntimeException.class,
                schema::initializeValidators,
                "Exception from preloadJsonSchema should propagate");
        Assertions.assertEquals("preload failure", ex.getMessage());

        // Verify only the first (failing) validator was invoked
        Assertions.assertEquals(1, badValidator.getPreloadCalls(),
                "badValidator should have been invoked once");
        Assertions.assertEquals(0, goodValidator.getPreloadCalls(),
                "goodValidator must not have been invoked");

        // Flag must remain false because loading did not complete
        Assertions.assertFalse(isValidatorsLoaded(schema),
                "validatorsLoaded must remain false after exception");
    }

    @Test
    void initializeValidators_emptyValidatorList_setsFlag() throws Exception {
        List<JsonValidator> empty = Collections.emptyList();
        JsonSchema schema = createSchema(empty, false);
        schema.initializeValidators();

        // No validator to interact with – just check the flag
        Assertions.assertTrue(isValidatorsLoaded(schema),
                "validatorsLoaded should be true even with no validators");
    }

    @Test
    void initializeValidators_recoveryAfterException() throws Exception {
        // First call: a validator that throws
        StubValidator failing = new StubValidator();
        failing.setException(new RuntimeException("first failure"));
        JsonSchema schema = createSchema(Collections.singletonList(failing), false);

        // First invocation – expect exception, flag stays false
        Assertions.assertThrows(RuntimeException.class, schema::initializeValidators);
        Assertions.assertFalse(isValidatorsLoaded(schema),
                "Flag must stay false after first failure");

        // Replace the validator list with healthy ones
        StubValidator healthy1 = new StubValidator();
        StubValidator healthy2 = new StubValidator();
        setValidators(schema, Arrays.asList(healthy1, healthy2));

        // Second invocation – should succeed
        schema.initializeValidators();
        Assertions.assertEquals(1, healthy1.getPreloadCalls(),
                "healthy1 should be preloaded once");
        Assertions.assertEquals(1, healthy2.getPreloadCalls(),
                "healthy2 should be preloaded once");
        Assertions.assertTrue(isValidatorsLoaded(schema),
                "Flag should become true after successful retry");
    }

    @Test
    void initializeValidators_nullElementInList_throwsNPE() throws Exception {
        StubValidator afterNull = new StubValidator();
        List<JsonValidator> listWithNull = Arrays.asList(null, afterNull);
        JsonSchema schema = createSchema(listWithNull, false);

        NullPointerException npe = Assertions.assertThrows(NullPointerException.class,
                schema::initializeValidators,
                "Calling preloadJsonSchema on a null element should throw NPE");

        // Ensure the second validator was never touched
        Assertions.assertEquals(0, afterNull.getPreloadCalls(),
                "afterNull must not have been invoked");
        Assertions.assertFalse(isValidatorsLoaded(schema),
                "validatorsLoaded must remain false after NPE");
    }

    @Test
    void initializeValidators_duplicateValidators_callsPreloadPerEntry() throws Exception {
        StubValidator dup = new StubValidator();
        List<JsonValidator> dupList = Arrays.asList(dup, dup, dup);
        JsonSchema schema = createSchema(dupList, false);
        schema.initializeValidators();

        Assertions.assertEquals(3, dup.getPreloadCalls(),
                "Duplicate validator should be preloaded for each occurrence");
        Assertions.assertTrue(isValidatorsLoaded(schema),
                "Flag should be true after processing duplicates");
    }

    // -----------------------------------------------------------------------
    // The following two tests from the original suite required the ability to
    // make {@code getValidators()} throw an exception or return {@code null}.
    // Those behaviours are not achievable without a subclass or a mocking
    // framework, so they have been omitted from this self‑contained version.
    // -----------------------------------------------------------------------
}
